<script lang="ts">
 import { onMount } from 'svelte';
 import { authClient } from '$lib/auth-client'; import { translator } from '$lib/app-i18n'; import { goto } from '$app/navigation';
 let ready=$state(false);onMount(()=>ready=true);
 let {data}=$props();let t=$derived(translator(data.lang));let create=$state(false),email=$state(''),password=$state(''),name=$state(''),message=$state(''),busy=$state(false),second=$state(false),code=$state('');
 async function submit(){busy=true;message='';try{const result=second?await authClient.twoFactor.verifyTotp({code}):create?await authClient.signUp.email({email,password,name}):await authClient.signIn.email({email,password});if(result.error){message=result.error.message??'Error';return;}if(result.data && 'twoFactorRedirect' in result.data && result.data.twoFactorRedirect){second=true;return;}await goto(data.returnTo);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<svelte:head><title>Vinea · {t('signin')}</title></svelte:head>
<main class="auth"><a class="brand" href="/">Vinea <span>WINZERAPP</span></a><div class="languages">{#each ['de','en','it','fr'] as lang}<a href={'?lang='+lang}>{lang.toUpperCase()}</a>{/each}</div><h1>{t('welcome')}</h1><p>{t('authInfo')}</p><form onsubmit={(e)=>{e.preventDefault();submit();}}>{#if second}<label>{t('totp')}<input bind:value={code} required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" /></label>{:else}{#if create}<label>{t('name')}<input bind:value={name} required autocomplete="name" /></label>{/if}<label>{t('email')}<input type="email" bind:value={email} required autocomplete="email" /></label><label>{t('password')}<input type="password" bind:value={password} required minlength="12" maxlength="128" autocomplete={create?'new-password':'current-password'} /></label>{/if}<button disabled={!ready||busy}>{busy?t('saving'):t(second?'verify':create?'signup':'signin')}</button></form>{#if message}<p role="alert">{message}</p>{/if}{#if data.mailEnabled}<a href="/reset">{t('resetPassword')}</a>{/if}{#if !second}<button disabled={!ready} class="switch" onclick={()=>{create=!create;message='';}}>{t(create?'signin':'signup')}</button>{/if}</main>
<style>:global(body){margin:0;background:#f7f6f2;color:#263b32;font-family:Inter,system-ui,sans-serif}.auth{max-width:440px;margin:7vh auto;padding:32px}.brand{color:#234d3b;text-decoration:none;font:600 35px Georgia,serif}.brand span{font:10px system-ui;letter-spacing:3px;margin-left:12px}.languages{display:flex;gap:16px;margin:28px 0}.languages a{color:#45634e;font-size:12px}h1{font:36px Georgia,serif}p{color:#67756b;line-height:1.6}label{display:grid;gap:8px;margin:20px 0;font-size:14px}input{padding:14px;border:1px solid #d2d9d0;border-radius:8px;font:inherit;background:white}button{padding:14px;border:0;border-radius:8px;background:#26553e;color:white;font:inherit;width:100%;cursor:pointer}.switch{color:#26553e;background:transparent;margin-top:12px}button:disabled{opacity:.5}</style>
